MATCH (d:Drug)
WHERE d.commonName IN ["Carprofen", "Pindolol", "Temelimab", "Timolol", "Betamethasone"]
  AND NOT (
    EXISTS { MATCH (d)-[:CHEMICALDECREASESEXPRESSION]->(:Gene {geneSymbol: "VEGFA"}) }
    AND
    EXISTS { MATCH (d)-[:CHEMICALDECREASESEXPRESSION]->(:Gene {geneSymbol: "NVL"}) }
  )
OPTIONAL MATCH (d)-[r1:CHEMICALDECREASESEXPRESSION]->(g1:Gene {geneSymbol: "VEGFA"})
OPTIONAL MATCH (d)-[r2:CHEMICALDECREASESEXPRESSION]->(g2:Gene {geneSymbol: "NVL"})
RETURN d, r1, g1, r2, g2;
